// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CiType) predicate.CiType {
	return predicate.CiType(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CiType) predicate.CiType {
	return predicate.CiType(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CiType) predicate.CiType {
	return predicate.CiType(sql.NotPredicates(p))
}
